import{_ as s,o as t,c as e,a2 as i}from"./chunks/framework.YT-FC_Xx.js";const c=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1792750293000}'),n={name:"guide/getting-started.md"};function r(o,a,l,h,p,d){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>用一台服务器搭一个 VLESS Reality 节点，经中转服务器对接，最后用订阅导入客户端。先了解名词可以看 <a href="./concepts">基本概念</a>。</p><h2 id="_1-安装面板" tabindex="-1">1. 安装面板 <a class="header-anchor" href="#_1-安装面板" aria-label="Permalink to &quot;1. 安装面板&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kure29/flyx/releases/latest/download/panel_install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./panel_install.sh</span></span></code></pre></div><p>选 <code>1. 安装面板</code>，完成后访问 <code>http://服务器IP:6366</code>，默认账号 <code>admin_user</code> / <code>admin_user</code>，<strong>登录后立即修改密码</strong>。</p><p>详见 <a href="./install">安装面板</a>。</p><h2 id="_2-添加服务器" tabindex="-1">2. 添加服务器 <a class="header-anchor" href="#_2-添加服务器" aria-label="Permalink to &quot;2. 添加服务器&quot;">​</a></h2><ol><li><strong>设置 → 基本</strong> 里填好“面板后端地址”（服务器用它连接面板）</li><li><strong>服务器</strong> 页新建两台服务器（一台搭节点、一台当中转），点 <strong>安装</strong> 复制生成的命令，到对应服务器上以 root 执行</li><li>等服务器状态变为 <strong>在线</strong></li></ol><p>详见 <a href="./agent">安装 agent</a>。</p><h2 id="_3-搭建节点" tabindex="-1">3. 搭建节点 <a class="header-anchor" href="#_3-搭建节点" aria-label="Permalink to &quot;3. 搭建节点&quot;">​</a></h2><ol><li><strong>服务器</strong> 页 → <strong>内核</strong> 标签 → <strong>安装内核</strong>，在搭节点的服务器上安装 Xray</li><li><strong>节点</strong> 页 → <strong>入站</strong> 标签 → <strong>新建入站</strong> → 选这台服务器和 Xray → 点模板 <strong>VLESS + Reality + Vision</strong> → <strong>创建并下发</strong></li></ol><p>想知道该选哪个内核、哪个协议，见 <a href="./kernels">内核与协议</a>；入站的更多选项见 <a href="./nodes">新建入站</a>。</p><h2 id="_4-对接中转-可选" tabindex="-1">4. 对接中转（可选） <a class="header-anchor" href="#_4-对接中转-可选" aria-label="Permalink to &quot;4. 对接中转（可选）&quot;">​</a></h2><ol><li><strong>中转</strong> 页 → <strong>隧道</strong> 标签新建隧道，入口选中转机</li><li><strong>中转</strong> 页 → <strong>线路</strong> 标签，点节点 → 选这条隧道（也可以在节点页点入站 → <strong>中转</strong>）</li></ol><p>详见 <a href="./relay">对接中转</a>。已有别处搭好的节点，可以用 <a href="./import">导入节点</a>。</p><h2 id="_5-导入客户端" tabindex="-1">5. 导入客户端 <a class="header-anchor" href="#_5-导入客户端" aria-label="Permalink to &quot;5. 导入客户端&quot;">​</a></h2><p><strong>订阅</strong> 页里默认有一个“我的订阅”，点开它选客户端一键导入（Clash、sing-box、Shadowrocket、Loon、Quantumult X、Surge、Stash），或复制链接。直连和中转线路都在里面。</p><p>想按地区拆分、改名或分给朋友，见 <a href="./subscription">订阅与客户端</a>。</p><h2 id="_6-看延迟-可选" tabindex="-1">6. 看延迟（可选） <a class="header-anchor" href="#_6-看延迟-可选" aria-label="Permalink to &quot;6. 看延迟（可选）&quot;">​</a></h2><p><strong>设置 → 延迟测试点</strong> 点 <strong>添加三网推荐</strong>，服务器就会定时测到北京 / 上海 / 广东三网的延迟，并检测回程线路（CN2 GIA、9929、CMIN2 等），结果显示在节点和服务器卡片上。详见 <a href="./latency">延迟与回程</a>。</p><div class="tip custom-block"><p class="custom-block-title">复制失败？</p><p>浏览器只在 HTTPS 页面里完全开放复制功能。建议给面板配置域名和 HTTPS，见 <a href="./install#反向代理-可选">安装面板 - 反向代理</a>。</p></div>',21)])])}const k=s(n,[["render",r]]);export{c as __pageData,k as default};
